var editor,html="",isNew=false,_imgSrc="../images";function initForm(){getCurrentUser();displayCurrentUser(_imgSrc);$("#header").html(buildHeaderContent(_imgSrc));$("#navigation").html(buildMenuHtml(_imgSrc));refreshRecent(_imgSrc);initMenu();authorizePageViewAdmin();$.ajaxSetup({cache:false});activateAutoCompletes(ITEM_TYPE_HELP_SECTION);$("#lstItems").focus();$("#lstItems").autocomplete("close");$("#accordion").accordion({autoHeight:false,collapsible:true,icons:{header:null,headerSelected:null}});$(".sortable").sortable({revert:true,stop:function(event,ui){onPropertyGroupDropped(ui)}});$(".draggable").draggable({connectToSortable:".sortable",helper:"clone",revert:"invalid"});$("ul, li").disableSelection()}function createEditor(editorText){if(editor)return;var config={};editor=CKEDITOR.appendTo("editor",config,editorText)}function removeEditor(){if(!editor)return;document.getElementById("editorcontents").innerHTML=html=editor.getData();document.getElementById("contents").style.display="";editor.destroy();editor=null}function clearForm_HelpSection(){}function displayHelpSection(helpSection){$("#lblId").text(helpSection.Id);$("#txtTitle").val(helpSection.Title);$("#txtOrder").val(helpSection.Order);var html=[];html.push('<select id="lstImages" style="width:100%;" class="ui-widget ui-widget-content" onChange="onImageChanged()">');html.push('<option value="'+NULL_GUID+'">[Select]</option>');$.each(imageDictionary_GetSystem(),function(index,item){html.push('<option value="'+item.key+'">'+item.value+"</option>")});html.push("</select>");$("#tdImages").html(html.join(""));$("#lstImages").val(helpSection.ImageId);$("#accordion").show();removeEditor();createEditor(helpSection.Content);$("#tblButtons").show();toggleButtons("deleteButtons",true);toggleButtons("killButtons",USER_CURRENT.IsAdmin);toggleButtons("submitButtons",true)}function onDeleteClicked(){}function onDiscardChanges(){showMessage("Error","onDiscardChanges() not yet implemented",true,400,true)}function onImageChanged(){var newValue=$("#lstImages").val();if(newValue!=SELECTED_ITEM.ImageId){SELECTED_ITEM.ImageId=newValue;SELECTED_ITEM.IsDirty=true;itemModified(true)}}function onSaveClicked(){var oEditor=CKEDITOR.instances.editor1;SELECTED_ITEM.Content=oEditor.getData();var saved=helpSection_Save(SELECTED_ITEM),msg=null;if(saved){SELECTED_ITEM=helpSection_Get(SELECTED_ITEM.Id);displayHelpSection(SELECTED_ITEM);if(isNew){$("#lstItems").val(SELECTED_ITEM.Title);$("#lstItems-id").val(SELECTED_ITEM.Id)}msg="Help Section saved successfully.";toggleButtons("resetButtons",false);toggleButtons("submitButtons",false)}else msg="An error occured while saving the help section";showMessage("Result",msg,true,400,true)}function onTitleChanged(){var newValue=$("#txtTitle").val();if(newValue!=SELECTED_ITEM.Title){SELECTED_ITEM.Title=newValue;SELECTED_ITEM.IsDirty=true;itemModified(true)}}function onOrderChanged(){var newValue=$("#txtOrder").val();if(newValue!=SELECTED_ITEM.Order){SELECTED_ITEM.Order=newValue;SELECTED_ITEM.IsDirty=true;itemModified(true)}}function createItem(){SELECTED_ITEM=helpSection_Create(USER_CURRENT.Id);if(SELECTED_ITEM!==null&&SELECTED_ITEM!=undefined){clearForm_HelpSection();displayHelpSection(SELECTED_ITEM)}else showMessage("Error","Request to create a new help section failed",true,400,true)}